INSERT INTO public.product (product_id, product_name, product_ref, product_desc, product_categorie, product_create_at, product_marque_id, product_category_id) VALUES
	(1, 'Sac à dos Premium Zéphyr', 'REF-00001', 'Sac à dos Premium Zéphyr : Immense nom ligne véritable absolument qualité mettre guerre neuf tomber rentrer témoin poste compagnie rond bouche. Oeuvre entier soulever genre oiseau pour désigner former été écouter revoir champ observer.', 'Sacs', '2025-02-08 19:18:57+01', 14, 11),
	(2, 'Montre connectée Pro Nordik', 'REF-00002', 'Montre connectée Pro Nordik : Également préférer simplement prétendre traîner part coup paquet écarter étendue plein visible pendant valoir lieu poursuivre entourer. Réclamer moi nécessaire très presser pleurer suivre.', 'Montres', '2025-02-05 11:25:40+01', 1, 12),
	(3, 'Sac bandoulière Eco Lunaris', 'REF-00003', 'Sac bandoulière Eco Lunaris : Du séparer rire maintenant air chasser plaisir couleur raconter claire dur dessiner secrétaire posséder écraser rapide ancien. Bonheur soldat quartier soin quel miser demeurer répondre retourner durant pied.', 'Sacs', '2025-02-17 11:45:19+01', 18, 11),
	(4, 'Coussin Origine Fjord & Co', 'REF-00004', 'Coussin Origine Fjord & Co : Fixe vague vif enfance métier action dessus pain rentrer sombre sauter temps près paysan rappeler. Quarante côté projet convenir hors vite autrement vent puissant carte appartenir douter.', 'Décoration', '2025-07-22 18:05:18+02', 7, 15),
	(5, 'Bottines Studio Brisa', 'REF-00005', 'Bottines Studio Brisa : Certain nerveux devant époque presque choix chiffre entourer arrêter toute où peuple justice. Mer autre présent maître vaincre madame repousser cinquante meilleur français étranger sourd phrase.', 'Bottes', '2024-12-29 11:47:09+01', 6, 10),
	(6, 'Tote bag Édition limitée Océane', 'REF-00006', 'Tote bag Édition limitée Océane : Exposer dame rang manger vrai saisir visible accorder plaine hiver tandis que oreille paix valoir. Figure retirer calme deviner profondément air l''un rejeter lourd loi.', 'Sacs', '2025-06-21 16:59:40+02', 5, 11),
	(7, 'Bande élastique Pro Altavia', 'REF-00007', 'Bande élastique Pro Altavia : Approcher surprendre contre lourd troubler combien vague marquer accomplir aucun plan religion soin gouvernement bouche marquer premier. Paysage travailler qui chiffre important éprouver bataille article rester million moyen.', 'Fitness', '2025-07-25 15:45:57+02', 2, 14),
	(8, 'Sneakers Origine Kestrel', 'REF-00008', 'Sneakers Origine Kestrel : Tempête froid humain franchir engager fleur caractère accepter prochain attitude queue après. Exiger lier eaux pont oeuvre drame.', 'Baskets', '2025-07-23 13:16:03+02', 4, 9),
	(9, 'Bougie Léger Haussmann', 'REF-00009', 'Bougie Léger Haussmann : Figure sac amuser chute dangereux qui retirer serrer écraser parti effort souvenir verre soit peau vaincre. Midi mieux ce accent nouveau marier.', 'Décoration', '2025-02-02 04:59:28+01', 13, 15),
	(10, 'Veste Pro Maison Lumen', 'REF-00010', 'Veste Pro Maison Lumen : Émotion quoi taille éteindre gagner pays lorsque claire dans. Corde confiance réunir seul seuil toute vouloir impossible mentir.', 'Vestes', '2025-07-05 13:35:42+02', 3, 8),
	(11, 'Haltères Eco Haussmann', 'REF-00011', 'Haltères Eco Haussmann : Plante dessiner cou nature un exiger planche delà droite auteur convenir jour envoyer. Pourquoi chez mon rien valoir comme enfance reposer prêter.', 'Fitness', '2025-07-22 19:06:01+02', 13, 14),
	(12, 'Montre connectée Studio Zéphyr', 'REF-00012', 'Montre connectée Studio Zéphyr : Doucement expérience poète éprouver jeu hiver remercier journal brusquement payer avouer douze salut suffire côté puisque. Avant avancer agir livre amuser naturellement françois nombre tapis mesure mêler y interroger remettre.', 'Montres', '2025-08-08 17:11:51+02', 14, 12),
	(13, 'Montre Studio Piquet', 'REF-00013', 'Montre Studio Piquet : Folie suffire nom signer cesser liberté beaucoup face acheter dent véritable vision politique rassurer. Homme conclure trouver petit verser pur joindre.', 'Montres', '2025-09-18 11:21:21+02', 11, 12),
	(14, 'Blouson Origine Brisa', 'REF-00014', 'Blouson Origine Brisa : Appartenir recommencer dégager discours delà plaine lune respecter fixer terreur soulever appartement peine bord. Parti donner que naissance montrer ferme feu noir surprendre avec dessus vieil.', 'Vestes', '2025-09-14 14:17:12+02', 6, 8),
	(15, 'Chelsea boots Heritage Altavia', 'REF-00015', 'Chelsea boots Heritage Altavia : Lumière étude sol journal jeunesse occuper libre chance colon avant paupière crier. Ciel observer rouge peu garder épaule calme pluie.', 'Bottes', '2025-05-12 16:26:42+02', 2, 10),
	(16, 'Doudoune Urbain Lunaris', 'REF-00016', 'Doudoune Urbain Lunaris : Cri claire scène aile apprendre mourir claire parfois apparence mort aspect devoir condition valeur nul moindre. Souffler proposer sable trop curieux oeuvre.', 'Vestes', '2025-04-10 09:47:55+02', 18, 8),
	(17, 'Tote bag Pro Maison Lumen', 'REF-00017', 'Tote bag Pro Maison Lumen : Soit commencer sauter objet rester ruine confiance petit discours profondément etc idée nombreux décrire fin brûler. Maintenant tellement politique salut oeil compte tâche nul.', 'Sacs', '2025-07-04 13:08:03+02', 3, 11),
	(18, 'Théière Active Brisa', 'REF-00018', 'Théière Active Brisa : Lier car joie certain occasion sang sûr remercier pencher main fatigue apprendre malheur décrire réveiller résister figure. Revoir te seconde muet grâce devant réfléchir témoin bande nuage mêler devoir accent.', 'Cuisine', '2025-06-23 08:43:52+02', 6, 16),
	(19, 'Sneakers Édition limitée Altavia', 'REF-00019', 'Sneakers Édition limitée Altavia : Naissance caractère accomplir perdu porter enfoncer exprimer choix. Détruire siècle goutte faible dos point rappeler garçon répéter joie fatigue mieux deux.', 'Baskets', '2025-04-18 22:36:51+02', 2, 9),
	(20, 'Short de running Essentiel Fjord & Co', 'REF-00020', 'Short de running Essentiel Fjord & Co : Musique remarquer fort chambre société carte décrire repas trouver bois loi repousser réussir. Pouvoir présent clair vérité accent beauté chasser ton habitude au d''autres avis apercevoir.', 'Running', '2025-01-17 05:42:45+01', 7, 13),
	(21, 'Montre Origine Atelier Vega', 'REF-00021', 'Montre Origine Atelier Vega : Tout fou personnage du ventre assister remarquer complètement le acheter servir tout lune corde répondre. Lumière dégager comme animer dent à ciel vrai rendre étudier force nez.', 'Montres', '2025-04-25 16:25:13+02', 8, 12),
	(22, 'Sac bandoulière Classique Haussmann', 'REF-00022', 'Sac bandoulière Classique Haussmann : Affirmer prendre tête mentir promettre mine nécessaire étouffer rose début vent il français absolument complet lit mince. Écouter trop révéler vague sorte rôle moyen pourquoi vers moindre regretter rassurer.', 'Sacs', '2025-05-24 02:11:19+02', 13, 11),
	(23, 'Débardeur Confort Océane', 'REF-00023', 'Débardeur Confort Océane : Point supposer six jeunesse devoir fil résistance dans préférer réunir fusil étudier mari précis diriger durant. Plein sable avant tout jambe étudier sujet divers trop poitrine témoin.', 'T-shirts', '2025-06-21 12:06:46+02', 5, 6),
	(24, 'Blouson Signature Zéphyr', 'REF-00024', 'Blouson Signature Zéphyr : Quand demain depuis discuter décrire se second exécuter rencontrer cas avec vague larme accompagner signer valeur sept. Pain large voici sûr soleil justice vivre terrain doux d''autres.', 'Vestes', '2025-07-02 09:47:39+02', 14, 8),
	(25, 'Poêle Édition limitée Atelier Vega', 'REF-00025', 'Poêle Édition limitée Atelier Vega : Cependant maître goût travailler ancien étonner simple remonter immense cas lune enfoncer accorder pleurer feuille bon expression six. Mener demander intérieur ordre faible leur creuser précis.', 'Cuisine', '2025-02-25 11:13:10+01', 8, 16),
	(118, 'EDGE nombreuses_variantes 03', 'REF-00118', 'Produit de test « nombreuses_variantes ». Attaquer femme effacer cheveu courir apercevoir tombe.', 'Pantalons', '2025-06-15 08:11:37+02', 7, 7),
	(26, 'Jogging Heritage Piquet', 'REF-00026', 'Jogging Heritage Piquet : Façon fou huit mort violence pont rompre prochain rêver mieux sien côte réunir quarante. Révolution comprendre lever voyage serrer l''un prochain reposer eh mode monsieur fort.', 'Pantalons', '2025-08-25 13:57:44+02', 11, 7),
